import {BODY_AREAS,STYLES,ROUTINES,PROGRAMS,catalogSession,buildCustomSession} from './catalog.js';
import {EXERCISES,movementArt} from './exercises.js';
import {exerciseAllowed} from './planner.js';
import {dateKey,daysBetween,formatTime,activitySummary} from './engine.js';
import {calendarICS,nextReminder,reminderDue} from './reminders.js';

const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const addDays=(date,count)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+count);return dateKey(d);};
const label=(entries,id)=>entries.find(x=>x.id===id)?.name||id;
const id=win=>win.crypto?.randomUUID?.()||'routine-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);

export function programSchedule(program,profile){
  let previousDemanding=false;
  return Array.from({length:program.durationWeeks*7},(_,offset)=>{
    const date=addDays(program.startDate,offset),scheduled=profile.days.includes(new Date(date+'T12:00:00').getDay());
    const recovery=scheduled&&previousDemanding;
    previousDemanding=scheduled&&!recovery;
    return {date,scheduled,recovery,week:Math.floor(offset/7)+1,offset};
  });
}

// Original body-area artwork; these highlights identify a browsing category.
export function bodyArt(area='full'){
  const highlight=parts=>parts.includes(area)||area==='full'?'#ff793b':'#d5d8e0';
  return `<svg viewBox="0 0 140 160" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><ellipse cx="70" cy="151" rx="42" ry="4" fill="#c4c7d3" opacity=".25"/><circle cx="70" cy="19" r="13" fill="#afb6c8"/><path d="M60 33h20l15 10-7 44-10 11H62L52 87l-7-44z" fill="#aab3c6"/><path d="m48 43-12 34-7 27 9 3 11-24 12-35M92 43l12 34 7 27-9 3-11-24-12-35" fill="${highlight(['arms'])}"/><path d="m53 45 16 3v19H53zM87 45 71 48v19h16z" fill="${highlight(['chest','back'])}"/><path d="M57 69h12v24H60zM71 69h12l-3 24h-9z" fill="${highlight(['abs','core','back'])}"/><path d="M61 96h18l7 16-16 3-16-3z" fill="${highlight(['glutes'])}"/><path d="m55 111 13 3-4 35H53zM85 111l-13 3 4 35h11z" fill="${highlight(['legs','glutes'])}"/><path d="M49 149h17v5H49zM75 149h17v5H75z" fill="#7d879e"/></svg>`;
}

export function initFitness(win,api){
  const doc=win.document,$=x=>doc.getElementById(x),state=()=>api.getState(),esc=escapeHTML;
  let area='all',savedOnly=false,currentRoutine=null,currentProgram=null,draftRows=[],period='week',month=new Date(new Date().getFullYear(),new Date().getMonth(),1),lastTrack='';
  const abort=new win.AbortController();
  const on=(element,event,handler)=>element.addEventListener(event,handler,{signal:abort.signal});
  const modal=name=>{api.pause();const d=$(name);if(!d.open)d.showModal();};
  const close=name=>$(name).close();
  function commit(change){try{api.commit(change);return true;}catch(error){api.toast(error.message);return false;}}
  function feedback(routineId){const recent=[...state().workouts].reverse().find(w=>w.routineId===routineId&&w.difficultyFeedback);return recent?.soreness>=4?'hard':recent?.difficultyFeedback;}
  function descriptor(routine,minutes=routine.defaultMinutes,week=1){return catalogSession(state().profile,routine.id,{minutes:Number(minutes),week,feedback:feedback(routine.id)});}
  function availability(routine){try{descriptor(routine);return '';}catch(error){return error.message;}}

  function renderDiscover(){
    const p=state().profile;$('hero-athlete').innerHTML=bodyArt('full');$('discover-plan-summary').textContent=`${p.sessionMinutes} min / ${p.days.length} days a week / ${Math.ceil(daysBetween(p.startDate,p.deadline)/7)} weeks`;
    $('area-filters').innerHTML=[{id:'all',name:'All'},...BODY_AREAS].map(x=>`<button class="area-filter ${area===x.id?'selected':''}" data-area="${x.id}" aria-pressed="${area===x.id}"><span>${bodyArt(x.id==='all'?'full':x.id)}</span>${esc(x.name)}</button>`).join('');
    const query=$('routine-search').value.trim().toLowerCase(),style=$('routine-style').value,level=$('routine-level').value;
    const list=ROUTINES.filter(r=>(area==='all'||r.area===area)&&(style==='all'||r.style===style)&&(level==='all'||r.level===level)&&(!savedOnly||state().favorites.includes(r.id))&&(r.name+' '+r.description+' '+r.area+' '+r.style).toLowerCase().includes(query));
    $('catalog-heading').textContent=area==='all'?'Find your next workout.':label(BODY_AREAS,area)+' workouts';$('catalog-count').textContent=list.length+' workouts';
    $('routine-grid').innerHTML=list.map(r=>{const issue=availability(r),saved=state().favorites.includes(r.id),ex=EXERCISES[r.movements?.[0]];return `<article class="routine-card"><button class="favorite-btn" data-favorite="${r.id}" aria-label="${saved?'Unsave':'Save'} ${esc(r.name)}" aria-pressed="${saved}">${saved?'&#9829;':'&#9825;'}</button><button class="routine-cover" data-routine="${r.id}" aria-label="View ${esc(r.name)}">${ex?movementArt(ex.art):bodyArt(r.area)}<span class="routine-badge">${esc(label(STYLES,r.style))}</span></button><div class="routine-info"><h3>${esc(r.name)}</h3><div class="routine-meta"><span>${r.defaultMinutes} min</span><span>/</span><span>${esc(r.level)}</span></div><p>${esc(r.description)}</p>${issue?`<p class="availability-note">${esc(issue)}</p>`:''}<button class="outline-btn" data-routine="${r.id}">${issue?'View requirements':'View workout'} &rarr;</button></div></article>`;}).join('')||'<p class="empty-workouts">No matching workouts. Try another body area or clear a filter.</p>';
    $('program-grid').innerHTML=PROGRAMS.map(p=>`<article class="program-card"><span class="eyebrow">${p.challenge?'CHALLENGE':'STRUCTURED PROGRAM'} / ${p.weeks} WEEKS</span><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><button data-program="${p.id}">Choose program &rarr;</button></article>`).join('');
    $('custom-grid').innerHTML=state().customRoutines.map(r=>`<article class="routine-card"><div class="routine-cover">${movementArt(EXERCISES[r.movements[0].exercise].art)}<span class="routine-badge">YOUR ROUTINE</span></div><div class="routine-info"><h3>${esc(r.name)}</h3><p>${r.movements.length} movements / your activity and recovery intervals</p><div class="custom-card-actions"><button class="primary-btn" data-custom-start="${r.id}">Start</button><button class="text-btn" data-custom-edit="${r.id}">Edit</button><button class="text-btn" data-custom-delete="${r.id}" aria-label="Delete ${esc(r.name)}">Delete</button></div></div></article>`).join('')||'<p class="empty-workouts">Mix movements, change intervals and save a routine you enjoy. Choose “Build a routine” to get started.</p>';
  }

  function openRoutine(routineId){currentRoutine=ROUTINES.find(r=>r.id===routineId);if(!currentRoutine)return;const r=currentRoutine;$('routine-detail-name').textContent=r.name;$('routine-detail-kicker').textContent=label(BODY_AREAS,r.area)+' / '+label(STYLES,r.style)+' / '+r.level;$('routine-detail-description').textContent=r.description;$('routine-detail-art').innerHTML=bodyArt(r.area);
    if(![...$('routine-minutes').options].some(o=>Number(o.value)===r.defaultMinutes))$('routine-minutes').add(new win.Option(r.defaultMinutes+' minutes',String(r.defaultMinutes)));
    $('routine-minutes').value=String(r.defaultMinutes);previewRoutine();modal('routine-dialog');
  }
  function previewRoutine(){if(!currentRoutine)return;try{const d=descriptor(currentRoutine,$('routine-minutes').value),work=d.steps.filter(s=>s.type==='work'),unique=[...new Set(work.map(x=>x.exercise))];$('routine-detail-error').textContent='';$('routine-adaptation').textContent=d.adaptationReason||'Includes preparation, activity, recovery and cool-down. Your movement preferences apply.';$('routine-detail-moves').innerHTML=unique.map(x=>`<div>${movementArt(EXERCISES[x].art)}<div><strong>${esc(EXERCISES[x].name)}</strong><small>${work.filter(s=>s.exercise===x).length} activity windows</small></div></div>`).join('');$('load-routine').disabled=false;}catch(error){$('routine-detail-error').textContent=error.message;$('routine-detail-moves').replaceChildren();$('routine-adaptation').textContent='Adjust your training preferences or choose a suitable workout.';$('load-routine').disabled=true;}}
  function loadRoutine(){try{const d=descriptor(currentRoutine,$('routine-minutes').value);if(api.loadSession(d)){close('routine-dialog');api.showView('workout');}}catch(error){$('routine-detail-error').textContent=error.message;}}

  function customOptions(selected){return Object.values(EXERCISES).filter(e=>e.id!=='cool'&&(exerciseAllowed(state().profile,e.id)||e.id===selected)).map(e=>`<option value="${e.id}" ${selected===e.id?'selected':''}>${esc(e.name)}${exerciseAllowed(state().profile,e.id)?'':' (review preferences)'}</option>`).join('');}
  function collectRows(){draftRows=[...$('custom-movements').querySelectorAll('.custom-movement')].map(row=>({exercise:row.querySelector('[data-exercise]').value,work:Number(row.querySelector('[data-work]').value),rest:Number(row.querySelector('[data-rest]').value),rounds:Number(row.querySelector('[data-rounds]').value)}));}
  function renderRows(){$('custom-movements').innerHTML=draftRows.map((r,i)=>`<div class="custom-movement"><div class="custom-movement-header"><span>MOVEMENT ${i+1}</span><div><button type="button" data-row-up="${i}" aria-label="Move movement ${i+1} earlier" ${i===0?'disabled':''}>&uarr;</button><button type="button" data-row-down="${i}" aria-label="Move movement ${i+1} later" ${i===draftRows.length-1?'disabled':''}>&darr;</button><button type="button" data-row-remove="${i}" aria-label="Remove movement ${i+1}">&times;</button></div></div><select data-exercise aria-label="Movement ${i+1}">${customOptions(r.exercise)}</select><div class="custom-timing"><label>Activity (sec)<input data-work type="number" min="5" max="180" value="${r.work}" required></label><label>Rest (sec)<input data-rest type="number" min="0" max="180" value="${r.rest}" required></label><label>Rounds<input data-rounds type="number" min="1" max="5" value="${r.rounds}" required></label></div></div>`).join('');$('custom-movements').querySelectorAll('[data-exercise]').forEach((select,i)=>select.value=String(draftRows[i].exercise));builderTotal();}
  function readDraft(){collectRows();return {id:$('custom-id').value||id(win),name:$('custom-name').value.trim(),warmup:Number($('custom-warmup').value),cooldown:Number($('custom-cooldown').value),movements:draftRows.map(x=>({...x}))};}
  function builderTotal(){collectRows();const total=Number($('custom-warmup').value)+Number($('custom-cooldown').value)+draftRows.reduce((n,x)=>n+(x.work+x.rest)*x.rounds,0);$('builder-total').textContent=Number.isFinite(total)?'Planned session: '+formatTime(total)+' including preparation and recovery. Maximum 60 minutes.':'Check your intervals.';}
  function openBuilder(routine=null){$('custom-id').value=routine?.id||'';$('custom-name').value=routine?.name||'My workout';$('custom-warmup').value=routine?.warmup??120;$('custom-cooldown').value=routine?.cooldown??120;draftRows=routine?.movements?.map(x=>({...x}))||[{exercise:Object.values(EXERCISES).find(e=>e.id!=='cool'&&exerciseAllowed(state().profile,e.id))?.id||'march',work:30,rest:30,rounds:2}];$('builder-error').textContent='';renderRows();modal('builder-dialog');}
  function customDescriptor(r){return {...buildCustomSession(state().profile,r),routineId:r.id};}
  function saveCustom(event){event.preventDefault();try{const r=readDraft();customDescriptor(r);api.commit(s=>({...s,customRoutines:[...s.customRoutines.filter(x=>x.id!==r.id),r]}));close('builder-dialog');api.toast('Your workout is saved.');}catch(error){$('builder-error').textContent=error.message;}}
  function tryCustom(){try{const r=readDraft();if(api.loadSession(customDescriptor(r))){close('builder-dialog');api.showView('workout');}}catch(error){$('builder-error').textContent=error.message;}}
  function copySession(session,name){const rows=[];for(let i=0;i<session.steps.length;i++){const s=session.steps[i];if(s.type!=='work')continue;const next=session.steps[i+1];let work=s.duration,rest=next?.type==='rest'?next.duration:0;const pairIndex=i+(next?.type==='rest'?2:1),pair=session.steps[pairIndex];if(EXERCISES[s.exercise].bilateral&&pair?.type==='work'&&pair.exercise===s.exercise){work+=pair.duration;const after=session.steps[pairIndex+1];if(after?.type==='rest')rest+=after.duration;i=pairIndex;}rows.push({exercise:s.exercise,work,rest,rounds:1});}if(rows.length>30)throw new Error('This session has more than 30 activity windows. Build a shorter custom routine or copy a shorter session.');openBuilder({name:name||session.title,warmup:session.steps[0].duration,cooldown:session.steps.at(-1).duration,movements:rows});}

  function openProgram(programId){currentProgram=PROGRAMS.find(p=>p.id===programId);if(!currentProgram)return;$('program-detail-name').textContent=currentProgram.name;$('program-detail-description').textContent=currentProgram.description;$('program-start').value=dateKey();$('program-duration').value=String(currentProgram.weeks);$('program-error').textContent='';modal('program-dialog');}
  function enroll(event){event.preventDefault();try{const startDate=$('program-start').value,durationWeeks=Number($('program-duration').value),template=currentProgram,r=ROUTINES.find(x=>x.id===template.routineId);descriptor(r,state().profile.sessionMinutes);const next={id:template.id,instanceId:id(win),routineId:template.routineId,startDate,durationWeeks};api.commit(s=>({...s,activeProgram:next}));close('program-dialog');api.showView('plan');api.toast('Program started. Your selected days and session length apply.');}catch(error){$('program-error').textContent=error.message;}}
  function programDateSession(date){const program=state().activeProgram;if(!program)return;const r=ROUTINES.find(x=>x.id===program.routineId),p=state().profile,entry=programSchedule(program,p).find(x=>x.date===date);if(!entry?.scheduled)throw new Error('Choose a scheduled day in this program.');const week=entry.week;
    const recovery=entry.recovery;
    const routine=recovery?ROUTINES.find(x=>x.id==='recovery-gentle'):r;
    const d=descriptor(routine,p.sessionMinutes,week);d.programId=program.instanceId;d.description=(recovery?'Lighter recovery between closely spaced training days. ': '')+(d.description||'');
    if(api.loadSession(d)){api.showView('workout');api.toast((recovery?'Recovery session / ':'Program session / ')+new Date(date+'T12:00:00').toLocaleDateString());}
  }
  function renderProgram(){const program=state().activeProgram;$('active-program').hidden=!program;if(!program)return;const template=PROGRAMS.find(x=>x.id===program.id),p=state().profile,total=program.durationWeeks*7,completed=new Set(state().workouts.filter(w=>w.programId===program.instanceId&&w.skipped===0&&w.seconds>0&&w.date>=program.startDate&&w.date<addDays(program.startDate,total)&&p.days.includes(new Date(w.date+'T12:00:00').getDay())).map(w=>w.date));$('active-program-name').textContent=template?.name||'Your program';$('active-program-summary').textContent=`${program.durationWeeks} weeks / ${p.days.length} training days per week / ${completed.size} completed days`;
    const schedule=programSchedule(program,p);const currentWeek=Math.max(0,Math.min(program.durationWeeks-1,Math.floor(daysBetween(program.startDate,dateKey())/7))),firstWeek=program.durationWeeks<=8?0:Math.max(0,currentWeek-1),lastWeek=program.durationWeeks<=8?program.durationWeeks:Math.min(program.durationWeeks,firstWeek+4);
    $('program-week-grid').innerHTML=Array.from({length:lastWeek-firstWeek},(_,i)=>{const week=firstWeek+i;return `<div class="program-week"><div class="program-week-header"><strong>WEEK ${week+1}</strong><span>${(week+1)%4===0?'Lighter week':'Practice & progress'}</span></div><div class="program-days">${Array.from({length:7},(_,day)=>{const {date,scheduled,recovery}=schedule[week*7+day],done=completed.has(date);return `<${scheduled?'button':'div'} ${scheduled?'data-program-date="'+date+'"':''} class="program-day ${scheduled?'scheduled':''} ${done?'done':''} ${date===dateKey()?'today':''}" title="${date}"><strong>${week*7+day+1}</strong><span>${done?'Completed':recovery?'Recovery':scheduled?label(BODY_AREAS,ROUTINES.find(x=>x.id===program.routineId)?.area):'Rest'}</span></${scheduled?'button':'div'}>`;}).join('')}</div></div>`;}).join('');
    if(program.durationWeeks>8)$('active-program-summary').textContent+=' / showing nearby weeks';
    const dates=schedule.filter(d=>d.scheduled&&d.date>=dateKey()).map(d=>d.date);const next=dates.find(d=>!completed.has(d));$('program-next').disabled=!next;$('program-next').textContent=next?'Open next session →':'Program finished — choose your next step';$('program-next').dataset.date=next||'';
  }

  function range(){const today=dateKey(),d=new Date();if(period==='all')return {from:'1900-01-01',to:today,today};if(period==='month')return {from:dateKey(new Date(d.getFullYear(),d.getMonth(),1)),to:today,today};return {from:dateKey(new Date(d.getFullYear(),d.getMonth(),d.getDate()-((d.getDay()+6)%7))),to:today,today};}
  function renderReports(){const r=activitySummary(state(),range());$('report-workouts').textContent=r.totalWorkouts;$('report-kcal').textContent=r.hasCalories?Math.round(r.kcal):'—';$('report-minutes').textContent=Math.round(r.minutes);$('report-streak').textContent=activitySummary(state(),{from:'1900-01-01',to:dateKey(),today:dateKey()}).streak;$('energy-note').textContent=r.hasCalories?'Energy totals are rough estimates for sessions with an estimate enabled. They include rest, may overestimate activity, and are not measured.':'Calories are optional. Enable adult energy estimates in Profile if you want a rough session total.';
    const all=activitySummary(state(),{from:'1900-01-01',to:dateKey(),today:dateKey()}),active=new Set(all.activityDates),complete=new Set(all.completedDates);$('report-month').textContent=month.toLocaleDateString(undefined,{month:'short',year:'numeric'});const days=new Date(month.getFullYear(),month.getMonth()+1,0).getDate(),offset=(month.getDay()+6)%7;
    $('report-calendar').innerHTML=['M','T','W','T','F','S','S'].map(x=>`<span class="calendar-day heading">${x}</span>`).join('')+'<span></span>'.repeat(offset)+Array.from({length:days},(_,i)=>{const date=dateKey(new Date(month.getFullYear(),month.getMonth(),i+1));return `<span class="calendar-day ${complete.has(date)?'complete':active.has(date)?'active':''} ${date===dateKey()?'today':''}" title="${date}: ${complete.has(date)?'completed workout':active.has(date)?'activity logged':'no logged activity'}">${i+1}</span>`;}).join('');
    const recent=Array.from({length:7},(_,i)=>{const date=addDays(dateKey(),i-6),day=all.calendar.find(x=>x.date===date);return {date,minutes:day?.minutes||0};}),max=Math.max(10,...recent.map(x=>x.minutes));$('duration-chart').innerHTML=recent.map(x=>`<div class="duration-bar" title="${x.date}: ${x.minutes.toFixed(1)} minutes"><strong>${Math.round(x.minutes)}</strong><div class="bar-wrap"><span style="height:${x.minutes/max*100}%"></span></div><small>${new Date(x.date+'T12:00:00').toLocaleDateString(undefined,{weekday:'short'})}</small></div>`).join('');
  }

  function renderSettings(){const s=state(),p=s.profile,r=s.settings.reminders;$('profile-name').textContent=p.name||'Your training space';$('profile-avatar').textContent=(p.name||'F').slice(0,1).toUpperCase();$('profile-detail').textContent=`${p.experience} / ${p.sessionMinutes}-minute sessions / ${p.days.length} training days`;
    if(!doc.activeElement?.closest('#reminder-form')){$('reminders-enabled').checked=r.enabled;$('reminder-time').value=r.time;$('reminder-days').innerHTML=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<label><input type="checkbox" name="reminder-day" value="${i}" ${r.days.includes(i)?'checked':''}><span>${d}</span></label>`).join('');const next=nextReminder(r);$('reminder-status').textContent=next?'Next reminder: '+new Date(next.date+'T12:00:00').toLocaleDateString()+' at '+next.time:'Reminders are off.';}
    $('settings-voice').checked=s.settings.voice;$('voice-toggle').textContent=s.settings.voice?'Voice on':'Voice off';$('voice-toggle').setAttribute('aria-pressed',String(s.settings.voice));if(!win.speechSynthesis||!win.SpeechSynthesisUtterance)$('voice-status').textContent='Speech is unavailable in this browser. Visual instructions and timer sounds remain available.';
    if(!doc.activeElement?.closest('#energy-form')){const e=s.settings.energy;$('energy-enabled').checked=e.enabled;$('energy-enabled').disabled=p.ageBand==='teen';$('energy-age').value=e.age??'';$('energy-weight').value=e.weight??'';$('energy-intensity').value=e.intensity;$('energy-settings-status').textContent=p.ageBand==='teen'?'Energy estimates are not part of teen plans.':'';}
  }
  function readReminder(){return {...state().settings.reminders,enabled:$('reminders-enabled').checked,time:$('reminder-time').value,days:[...doc.querySelectorAll('[name="reminder-day"]:checked')].map(e=>Number(e.value)),lastNotified:''};}
  function saveReminder(event){event.preventDefault();try{const r=readReminder();api.commit(s=>({...s,settings:{...s.settings,reminders:r}}));$('reminder-status').textContent=r.enabled?'Reminder schedule saved. Add it to your phone calendar for alerts while FORM is closed.':'Reminders turned off. Remove any previously imported calendar alerts separately.';}catch(error){$('reminder-status').textContent=error.message;}}
  function exportCalendar(){try{const r=state().settings.reminders;if(!r.enabled)throw new Error('Save an enabled reminder schedule first.');const program=state().activeProgram,profile=program?{...state().profile,startDate:program.startDate,deadline:addDays(program.startDate,program.durationWeeks*7)}:state().profile,ics=calendarICS(profile,r,program?.instanceId);api.download(ics,'FORM-training-reminders.ics','text/calendar;charset=utf-8');api.toast('Import the calendar file on your phone, then check its alert settings.');}catch(error){api.toast(error.message);}}
  function checkReminder(now=new Date()){const r=state().settings.reminders;if(!reminderDue(r,now))return;const key=dateKey(now)+'T'+r.time;if(!commit(s=>({...s,settings:{...s.settings,reminders:{...r,lastNotified:key}}})))return;api.toast('Your training reminder: take a manageable next step.');try{if(win.Notification?.permission==='granted')new win.Notification('Time for your FORM workout',{body:'Your routine is ready. Move at your pace.',tag:'form-training',icon:'./assets/icon-192.png'});}catch{}}
  function speak(step){if(!state().settings.voice||!win.speechSynthesis||!win.SpeechSynthesisUtterance)return;try{win.speechSynthesis.cancel();const utterance=new win.SpeechSynthesisUtterance((step.label||EXERCISES[step.exercise]?.name||'Next interval')+'. '+step.duration+' seconds.');utterance.rate=.95;win.speechSynthesis.speak(utterance);}catch{}}
  function updatePlayer(timer){const key=timer.steps.length+':'+timer.index;if(key!==lastTrack){$('interval-track').innerHTML=timer.steps.map((s,i)=>`<span class="${i<timer.index?'past':i===timer.index?'current':''}"></span>`).join('');lastTrack=key;} }

  $('routine-style').innerHTML='<option value="all">All styles</option>'+STYLES.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');
  on(doc,'click',event=>{const hit=key=>event.target.closest('['+key+']');let target;
    if((target=hit('data-experience'))){api.openGoal();$('goal-experience').value=target.dataset.experience;$('routine-level').value=target.dataset.experience;$('goal-experience').dispatchEvent(new win.Event('input',{bubbles:true}));}
    if((target=hit('data-area'))){area=target.dataset.area;renderDiscover();}
    if((target=hit('data-favorite')))commit(s=>({...s,favorites:s.favorites.includes(target.dataset.favorite)?s.favorites.filter(x=>x!==target.dataset.favorite):[...s.favorites,target.dataset.favorite]}));
    if((target=hit('data-routine')))openRoutine(target.dataset.routine);
    if((target=hit('data-program')))openProgram(target.dataset.program);
    if((target=hit('data-custom-edit')))openBuilder(state().customRoutines.find(x=>x.id===target.dataset.customEdit));
    if((target=hit('data-custom-start'))){try{const r=state().customRoutines.find(x=>x.id===target.dataset.customStart);if(api.loadSession(customDescriptor(r)))api.showView('workout');}catch(error){api.toast(error.message);}}
    if((target=hit('data-custom-delete'))&&win.confirm('Delete this saved workout? Past activity will remain in your reports.'))commit(s=>({...s,customRoutines:s.customRoutines.filter(x=>x.id!==target.dataset.customDelete)}));
    if((target=hit('data-row-up'))){collectRows();const i=Number(target.dataset.rowUp);[draftRows[i-1],draftRows[i]]=[draftRows[i],draftRows[i-1]];renderRows();}
    if((target=hit('data-row-down'))){collectRows();const i=Number(target.dataset.rowDown);[draftRows[i+1],draftRows[i]]=[draftRows[i],draftRows[i+1]];renderRows();}
    if((target=hit('data-row-remove'))){collectRows();draftRows.splice(Number(target.dataset.rowRemove),1);renderRows();}
    if((target=hit('data-program-date'))){try{programDateSession(target.dataset.programDate);}catch(error){api.toast(error.message);}}
    if((target=hit('data-period'))){period=target.dataset.period;doc.querySelectorAll('[data-period]').forEach(b=>b.classList.toggle('selected',b.dataset.period===period));renderReports();}
  });
  on($('routine-search'),'input',renderDiscover);on($('routine-style'),'change',renderDiscover);on($('routine-level'),'change',renderDiscover);on($('favorites-only'),'click',()=>{savedOnly=!savedOnly;$('favorites-only').setAttribute('aria-pressed',String(savedOnly));renderDiscover();});on($('routine-minutes'),'change',previewRoutine);on($('load-routine'),'click',loadRoutine);
  on($('copy-routine'),'click',()=>{try{const d=descriptor(currentRoutine,$('routine-minutes').value);copySession(d,currentRoutine.name+' / custom');close('routine-dialog');}catch(error){$('routine-detail-error').textContent=error.message;}});
  on($('discover-personal'),'click',()=>{api.selectPersonalized();api.showView('workout');if(!state().profile.safetyAccepted)api.openGoal();});on($('profile-preferences'),'click',api.openGoal);
  on($('open-builder'),'click',()=>openBuilder());on($('create-custom'),'click',()=>openBuilder());on($('add-custom-movement'),'click',()=>{collectRows();if(draftRows.length>=30){$('builder-error').textContent='Use up to 30 movements.';return;}draftRows.push({exercise:Object.values(EXERCISES).find(e=>e.id!=='cool'&&exerciseAllowed(state().profile,e.id))?.id||'march',work:30,rest:30,rounds:1});renderRows();});on($('builder-form'),'input',builderTotal);on($('builder-form'),'submit',saveCustom);on($('preview-custom'),'click',tryCustom);on($('edit-session'),'click',()=>{try{copySession({title:api.timer.sessionTitle,steps:api.timer.steps});}catch(error){api.toast(error.message);}});
  on($('program-form'),'submit',enroll);on($('program-next'),'click',()=>{try{if($('program-next').dataset.date)programDateSession($('program-next').dataset.date);}catch(error){api.toast(error.message);}});on($('leave-program'),'click',()=>{if(win.confirm('Leave this program? Your completed workouts will stay in your history.'))commit(s=>({...s,activeProgram:null}));});
  on($('calendar-prev'),'click',()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1);renderReports();});on($('calendar-next'),'click',()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1);renderReports();});on($('reminder-form'),'submit',saveReminder);on($('export-reminders'),'click',exportCalendar);
  on($('notification-permission'),'click',async()=>{if(!win.Notification){$('reminder-status').textContent='Browser alerts are unavailable here. Use the phone calendar option.';return;}try{const result=await win.Notification.requestPermission();$('reminder-status').textContent=result==='granted'?'Alerts allowed while FORM stays open. Import calendar alerts for reminders while closed.':'Browser alerts were not enabled. Calendar reminders remain available.';}catch{$('reminder-status').textContent='Browser alerts could not be enabled. Use the phone calendar option.';}});
  const toggleVoice=()=>{commit(s=>({...s,settings:{...s.settings,voice:!s.settings.voice}}));try{win.speechSynthesis?.cancel();}catch{}};on($('voice-toggle'),'click',toggleVoice);on($('settings-voice'),'change',()=>{commit(s=>({...s,settings:{...s.settings,voice:$('settings-voice').checked}}));});
  on($('energy-form'),'submit',event=>{event.preventDefault();try{const age=$('energy-age').value.trim(),weight=$('energy-weight').value.trim(),energy={enabled:$('energy-enabled').checked,age:age===''?null:Number(age),weight:weight===''?null:Number(weight),intensity:$('energy-intensity').value};api.commit(s=>({...s,settings:{...s.settings,energy}}));$('energy-settings-status').textContent=energy.enabled?'Rough estimates enabled for future sessions. Past totals are unchanged.':'Energy estimates are off.';}catch(error){$('energy-settings-status').textContent=error.message;}});
  const reminderInterval=win.setInterval(()=>checkReminder(),30000);
  return {render:()=>{renderDiscover();renderProgram();renderReports();renderSettings();},renderReports,updatePlayer,speak,stopVoice:()=>{try{win.speechSynthesis?.cancel();}catch{}},checkReminder,openBuilder,dispose:()=>{abort.abort();win.clearInterval(reminderInterval);try{win.speechSynthesis?.cancel();}catch{}}};
}
